Metrics List:
- {"name": "node_network_receive_errs_total", "type": "counter", "description": "Network device statistic receive_errs."}
- {"name": "container_network_transmit_errors_total", "type": "counter", "description": "Cumulative count of errors encountered while transmitting"}
- {"name": "container_network_receive_errors_total", "type": "counter", "description": "Cumulative count of errors encountered while receiving"}
- {"name": "node_sockstat_sockets_used", "type": "gauge", "description": "Number of IPv4 sockets in use."}
- {"name": "node_filesystem_device_error", "type": "gauge", "description": "Whether an error occurred while getting statistics for the given device."}
- {"name": "kube_pod_container_resource_requests", "type": "gauge", "description": "The number of requested request resource by a container. It is recommended to use the kube_pod_resource_requests metric exposed by kube-scheduler instead, as it is more precise."}
- {"name": "kube_pod_container_resource_limits", "type": "gauge", "description": "The number of requested limit resource by a container. It is recommended to use the kube_pod_resource_limits metric exposed by kube-scheduler instead, as it is more precise."}
- {"name": "node_network_dormant", "type": "gauge", "description": "Network device property: dormant"}
- {"name": "node_network_carrier_up_changes_total", "type": "counter", "description": "Network device property: carrier_up_changes_total"}
- {"name": "node_network_carrier_down_changes_total", "type": "counter", "description": "Network device property: carrier_down_changes_total"}
- {"name": "node_network_carrier_changes_total", "type": "counter", "description": "Network device property: carrier_changes_total"}
- {"name": "node_network_carrier", "type": "gauge", "description": "Network device property: carrier"}
- {"name": "node_network_address_assign_type", "type": "gauge", "description": "Network device property: address_assign_type"}
